"use client";

import {
  useMutation,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import { useRouter } from "next/navigation";
import {
  startTransition,
  useEffect,
  useEffectEvent,
  useMemo,
  useRef,
  useState,
} from "react";

import FlowCanvas from "@/app/components/FlowCanvas";
import PropertyInspector from "@/app/components/dashboard/PropertyInspector";
import Sidebar from "@/app/components/dashboard/Sidebar";
import Toolbar from "@/app/components/dashboard/Toolbar";
import { useAuth } from "@/app/context/AuthContext";
import { loadFlow, saveFlow } from "@/app/lib/api";
import type { WorkflowDocument } from "@/app/lib/types";
import { useWorkflowStore } from "@/app/store/workflowStore";

function serializeDocumentShape(document: {
  name: string;
  nodes: WorkflowDocument["nodes"];
  edges: WorkflowDocument["edges"];
  viewport: WorkflowDocument["viewport"];
}) {
  return JSON.stringify(document);
}

function getSuggestedInsertionPoint(nodes: WorkflowDocument["nodes"]) {
  if (nodes.length === 0) {
    return { x: 120, y: 120 };
  }

  const maxX = Math.max(...nodes.map((node) => node.position.x));
  const minY = Math.min(...nodes.map((node) => node.position.y));

  return {
    x: maxX + 320,
    y: minY + 40,
  };
}

export default function WorkflowDashboard() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { session, logout, isLoggingOut } = useAuth();

  const initialize = useWorkflowStore((state) => state.initialize);
  const nodes = useWorkflowStore((state) => state.nodes);
  const edges = useWorkflowStore((state) => state.edges);
  const name = useWorkflowStore((state) => state.name);
  const viewport = useWorkflowStore((state) => state.viewport);
  const hydrated = useWorkflowStore((state) => state.hydrated);
  const historyLength = useWorkflowStore((state) => state.history.length);
  const futureLength = useWorkflowStore((state) => state.future.length);
  const selectedNodeId = useWorkflowStore((state) => state.selectedNodeId);

  const [feedbackText, setFeedbackText] = useState<string | null>(null);

  const initializedUserRef = useRef<string | null>(null);
  const lastSyncedSignatureRef = useRef<string | null>(null);

  const currentSignature = useMemo(
    () => serializeDocumentShape({ name, nodes, edges, viewport }),
    [edges, name, nodes, viewport],
  );

  const selectedNode = useMemo(
    () => nodes.find((node) => node.id === selectedNodeId) ?? null,
    [nodes, selectedNodeId],
  );

  const flowQuery = useQuery({
    queryKey: ["flow", session?.user.id],
    enabled: Boolean(session?.user.id),
    queryFn: () => loadFlow(session!.user.id),
  });

  const manualSaveMutation = useMutation({
    mutationFn: saveFlow,
    onSuccess: (document) => {
      if (!session?.user.id) {
        return;
      }

      queryClient.setQueryData(["flow", session.user.id], document);
      lastSyncedSignatureRef.current = serializeDocumentShape(document);
      setFeedbackText("Saved to the local mock API.");
    },
  });

  const autosaveMutation = useMutation({
    mutationFn: saveFlow,
    onSuccess: (document) => {
      if (!session?.user.id) {
        return;
      }

      queryClient.setQueryData(["flow", session.user.id], document);
      lastSyncedSignatureRef.current = serializeDocumentShape(document);
      setFeedbackText("Autosaved locally.");
    },
  });

  useEffect(() => {
    if (!session?.user.id || !flowQuery.data) {
      return;
    }

    if (initializedUserRef.current === session.user.id) {
      return;
    }

    startTransition(() => {
      initialize(flowQuery.data);
    });

    initializedUserRef.current = session.user.id;
    lastSyncedSignatureRef.current = serializeDocumentShape(flowQuery.data);
  }, [flowQuery.data, initialize, session?.user.id]);

  async function runManualSave() {
    if (!session?.user.id) {
      return;
    }

    const workflowDocument = useWorkflowStore
      .getState()
      .exportDocument("manual");

    await manualSaveMutation.mutateAsync({
      userId: session.user.id,
      document: workflowDocument,
      mode: "manual",
    });
  }

  const runAutosave = useEffectEvent(async () => {
    if (!session?.user.id) {
      return;
    }

    const workflowDocument = useWorkflowStore
      .getState()
      .exportDocument("autosave");

    await autosaveMutation.mutateAsync({
      userId: session.user.id,
      document: workflowDocument,
      mode: "autosave",
    });
  });

  function insertTemplate(templateId: string) {
    const store = useWorkflowStore.getState();
    const insertionPoint = getSuggestedInsertionPoint(store.nodes);
    const template = store.addTemplate(templateId, insertionPoint);

    if (template) {
      setFeedbackText(`${template.name} inserted.`);
    }
  }

  function exportFlow() {
    const workflowDocument = useWorkflowStore
      .getState()
      .exportDocument("manual");
    const payload = JSON.stringify(workflowDocument, null, 2);
    const blob = new Blob([payload], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = `${workflowDocument.name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "") || "workflow"}.json`;
    link.click();

    URL.revokeObjectURL(url);
    setFeedbackText("Exported JSON blueprint.");
  }

  async function copyFlow() {
    try {
      const workflowDocument = useWorkflowStore
        .getState()
        .exportDocument("manual");
      await navigator.clipboard.writeText(JSON.stringify(workflowDocument, null, 2));
      setFeedbackText("Flow JSON copied to clipboard.");
    } catch {
      setFeedbackText("Clipboard access was blocked by the browser.");
    }
  }

  async function handleLogout() {
    await logout();
    router.replace("/auth/login");
  }

  const handleShortcut = useEffectEvent((event: KeyboardEvent) => {
    const target = event.target as HTMLElement | null;
    const isTextTarget =
      target?.tagName === "INPUT" ||
      target?.tagName === "TEXTAREA" ||
      target?.tagName === "SELECT" ||
      Boolean(target?.closest("[contenteditable='true']"));

    if (isTextTarget) {
      return;
    }

    const isModifier = event.metaKey || event.ctrlKey;
    const key = event.key.toLowerCase();
    const store = useWorkflowStore.getState();

    if ((event.key === "Delete" || event.key === "Backspace") && !isModifier) {
      event.preventDefault();
      store.deleteSelection();
      return;
    }

    if (isModifier && key === "s") {
      event.preventDefault();
      void runManualSave();
      return;
    }

    if (isModifier && key === "z") {
      event.preventDefault();

      if (event.shiftKey) {
        store.redo();
      } else {
        store.undo();
      }

      return;
    }

    if (isModifier && key === "y") {
      event.preventDefault();
      store.redo();
    }
  });

  useEffect(() => {
    window.addEventListener("keydown", handleShortcut);

    return () => {
      window.removeEventListener("keydown", handleShortcut);
    };
  }, []);

  useEffect(() => {
    if (!session?.user.id || !hydrated) {
      return;
    }

    if (currentSignature === lastSyncedSignatureRef.current) {
      return;
    }

    const timeout = window.setTimeout(() => {
      void runAutosave();
    }, 900);

    return () => {
      window.clearTimeout(timeout);
    };
  }, [currentSignature, hydrated, session?.user.id]);

  const statusText =
    feedbackText ??
    (flowQuery.isLoading
      ? "Restoring workspace..."
      : manualSaveMutation.isPending
        ? "Saving workspace..."
        : autosaveMutation.isPending
          ? "Autosaving..."
          : "Workspace loaded.");

  const lastSavedAt =
    manualSaveMutation.data?.updatedAt ??
    autosaveMutation.data?.updatedAt ??
    flowQuery.data?.updatedAt ??
    null;

  const lastSavedLabel = lastSavedAt
    ? new Intl.DateTimeFormat("en", {
        hour: "numeric",
        minute: "2-digit",
      }).format(new Date(lastSavedAt))
    : null;

  if (!session) {
    return (
      <div className="flex min-h-[70vh] items-center justify-center rounded-[32px] border border-slate-200 bg-white/80 p-8 text-center shadow-[0_18px_50px_rgba(15,23,42,0.08)] backdrop-blur">
        <div className="space-y-3">
          <p className="text-sm font-semibold uppercase tracking-[0.22em] text-slate-500">
            Restoring session
          </p>
          <h1 className="text-2xl font-semibold text-slate-900">
            Loading your dashboard shell...
          </h1>
          <p className="text-sm text-slate-500">
            The auth provider is syncing local session state before we mount the
            editor.
          </p>
        </div>
      </div>
    );
  }

  if (flowQuery.isLoading || !hydrated) {
    return (
      <div className="space-y-4">
        <div className="h-24 animate-pulse rounded-[28px] bg-white/70" />
        <div className="grid gap-4 xl:grid-cols-[300px_minmax(0,1fr)_320px]">
          <div className="h-[620px] animate-pulse rounded-[28px] bg-white/70" />
          <div className="h-[620px] animate-pulse rounded-[28px] bg-white/70" />
          <div className="h-[620px] animate-pulse rounded-[28px] bg-white/70" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <Toolbar
        userName={session.user.name}
        workflowName={name}
        statusText={statusText}
        lastSavedLabel={lastSavedLabel}
        canUndo={historyLength > 0}
        canRedo={futureLength > 0}
        isSaving={manualSaveMutation.isPending}
        isLoggingOut={isLoggingOut}
        onSave={() => void runManualSave()}
        onExport={exportFlow}
        onCopy={() => void copyFlow()}
        onUndo={() => useWorkflowStore.getState().undo()}
        onRedo={() => useWorkflowStore.getState().redo()}
        onLogout={() => void handleLogout()}
        onInsertTemplate={insertTemplate}
      />

      <div className="grid gap-4 xl:grid-cols-[300px_minmax(0,1fr)_320px]">
        <Sidebar
          nodeCount={nodes.length}
          edgeCount={edges.length}
          lastSavedLabel={lastSavedLabel}
          onInsertTemplate={insertTemplate}
        />

        <FlowCanvas />

        <PropertyInspector node={selectedNode} />
      </div>
    </div>
  );
}
