"use client";

import { useState } from "react";

import TemplatesLibrary from "@/app/components/dashboard/TemplatesLibrary";

type ToolbarProps = {
  userName: string;
  workflowName: string;
  statusText: string;
  lastSavedLabel: string | null;
  canUndo: boolean;
  canRedo: boolean;
  isSaving: boolean;
  isLoggingOut: boolean;
  onSave: () => void;
  onExport: () => void;
  onCopy: () => void;
  onUndo: () => void;
  onRedo: () => void;
  onLogout: () => void;
  onInsertTemplate: (templateId: string) => void;
};

export default function Toolbar({
  userName,
  workflowName,
  statusText,
  lastSavedLabel,
  canUndo,
  canRedo,
  isSaving,
  isLoggingOut,
  onSave,
  onExport,
  onCopy,
  onUndo,
  onRedo,
  onLogout,
  onInsertTemplate,
}: ToolbarProps) {
  const [showTemplates, setShowTemplates] = useState(false);

  return (
    <header className="relative rounded-[28px] border border-slate-200 bg-white/95 p-4 shadow-[0_18px_50px_rgba(15,23,42,0.08)] backdrop-blur">
      <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
        <div className="space-y-2">
          <div className="flex flex-wrap items-center gap-2 text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-500">
            <span className="rounded-full bg-sky-100 px-3 py-1 text-sky-700">
              Blueprint Studio
            </span>
            <span className="rounded-full bg-slate-100 px-3 py-1 text-slate-600">
              {workflowName}
            </span>
          </div>
          <div className="flex flex-wrap items-center gap-3 text-sm text-slate-500">
            <span>{statusText}</span>
            {lastSavedLabel ? <span>Saved {lastSavedLabel}</span> : null}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() => setShowTemplates((current) => !current)}
            className="rounded-2xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50"
          >
            Templates
          </button>

          <button
            type="button"
            onClick={onUndo}
            disabled={!canUndo}
            className="rounded-2xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50 disabled:cursor-not-allowed disabled:text-slate-300"
          >
            Undo
          </button>

          <button
            type="button"
            onClick={onRedo}
            disabled={!canRedo}
            className="rounded-2xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50 disabled:cursor-not-allowed disabled:text-slate-300"
          >
            Redo
          </button>

          <button
            type="button"
            onClick={onCopy}
            className="rounded-2xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50"
          >
            Copy JSON
          </button>

          <button
            type="button"
            onClick={onExport}
            className="rounded-2xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50"
          >
            Export
          </button>

          <button
            type="button"
            onClick={onSave}
            disabled={isSaving}
            className="rounded-2xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:bg-slate-400"
          >
            {isSaving ? "Saving..." : "Save"}
          </button>

          <div className="ml-1 flex items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5">
            <div className="text-right">
              <p className="text-xs font-semibold text-slate-900">{userName}</p>
              <p className="text-[11px] uppercase tracking-[0.18em] text-slate-500">
                editor
              </p>
            </div>
            <button
              type="button"
              onClick={onLogout}
              disabled={isLoggingOut}
              className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-100 disabled:cursor-not-allowed disabled:text-slate-300"
            >
              {isLoggingOut ? "Leaving..." : "Logout"}
            </button>
          </div>
        </div>
      </div>

      {showTemplates ? (
        <div className="absolute right-4 top-[calc(100%+12px)] z-20 w-full max-w-md rounded-[24px] border border-slate-200 bg-white p-4 shadow-[0_24px_80px_rgba(15,23,42,0.18)]">
          <TemplatesLibrary
            compact
            onApplyTemplate={(templateId) => {
              onInsertTemplate(templateId);
              setShowTemplates(false);
            }}
          />
        </div>
      ) : null}
    </header>
  );
}
