"use client";

import { TEMPLATE_LIBRARY } from "@/app/lib/workflow";

const TEMPLATE_MIME = "application/x-forgeflow-template";

type TemplatesLibraryProps = {
  compact?: boolean;
  allowDrag?: boolean;
  onApplyTemplate?: (templateId: string) => void;
};

export default function TemplatesLibrary({
  compact = false,
  allowDrag = false,
  onApplyTemplate,
}: TemplatesLibraryProps) {
  return (
    <section className="space-y-3">
      {!compact ? (
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-sm font-semibold text-slate-900">Template starters</h2>
            <p className="text-xs text-slate-500">
              Click to inject a starter or drag it straight onto the canvas.
            </p>
          </div>
          <span className="rounded-full bg-slate-100 px-2 py-1 text-[11px] font-medium text-slate-500">
            {TEMPLATE_LIBRARY.length} blueprints
          </span>
        </div>
      ) : null}

      <div className={compact ? "space-y-2" : "space-y-3"}>
        {TEMPLATE_LIBRARY.map((template) => (
          <div
            key={template.id}
            draggable={allowDrag}
            onDragStart={(event) => {
              if (!allowDrag) {
                return;
              }

              const payload = JSON.stringify({ templateId: template.id });
              event.dataTransfer.effectAllowed = "copy";
              event.dataTransfer.setData(TEMPLATE_MIME, payload);
              event.dataTransfer.setData("text/plain", payload);
            }}
            className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm transition hover:border-slate-300 hover:shadow-md"
          >
            <div className="flex items-start justify-between gap-3">
              <div className="space-y-1">
                <span className="inline-flex rounded-full bg-slate-100 px-2 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-500">
                  {template.category}
                </span>
                <h3 className="text-sm font-semibold text-slate-900">{template.name}</h3>
                <p className="text-xs leading-5 text-slate-500">
                  {template.description}
                </p>
              </div>

              <button
                type="button"
                onClick={() => onApplyTemplate?.(template.id)}
                className="shrink-0 rounded-xl border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-sky-200 hover:bg-sky-50 hover:text-sky-800"
              >
                Use
              </button>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
