"use client";

import { useState } from "react";

import type { WorkflowNode } from "@/app/lib/types";
import { useWorkflowStore } from "@/app/store/workflowStore";

type PropertyInspectorProps = {
  node: WorkflowNode | null;
};

export default function PropertyInspector({ node }: PropertyInspectorProps) {
  if (!node) {
    return (
      <aside className="flex h-full min-h-[360px] flex-col justify-between rounded-[28px] border border-slate-200 bg-white p-5 shadow-[0_18px_50px_rgba(15,23,42,0.08)]">
        <div className="space-y-3">
          <span className="inline-flex rounded-full bg-slate-100 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-500">
            Inspector
          </span>
          <h2 className="text-lg font-semibold text-slate-900">Select a node</h2>
          <p className="text-sm leading-6 text-slate-500">
            The property panel updates live as soon as a node is selected on the
            canvas.
          </p>
        </div>

        <div className="rounded-3xl border border-dashed border-slate-200 bg-slate-50 p-4 text-sm text-slate-500">
          Tip: use <span className="font-semibold text-slate-700">Delete</span> to
          remove a selected node, or{" "}
          <span className="font-semibold text-slate-700">Ctrl/Cmd + Z</span> to
          undo.
        </div>
      </aside>
    );
  }

  return <InspectorPanel key={node.id} node={node} />;
}

function InspectorPanel({ node }: { node: WorkflowNode }) {
  const updateNodeData = useWorkflowStore((state) => state.updateNodeData);
  const replaceNodeData = useWorkflowStore((state) => state.replaceNodeData);

  const [jsonDraft, setJsonDraft] = useState(() =>
    JSON.stringify(node.data, null, 2),
  );
  const [jsonError, setJsonError] = useState<string | null>(null);
  const [showJsonEditor, setShowJsonEditor] = useState(false);

  const configEntries = Object.entries(node.data.config);

  return (
    <aside className="flex h-full flex-col gap-4 overflow-hidden rounded-[28px] border border-slate-200 bg-white p-5 shadow-[0_18px_50px_rgba(15,23,42,0.08)]">
      <div className="flex items-start justify-between gap-3">
        <div className="space-y-1">
          <span className="inline-flex rounded-full bg-slate-100 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-500">
            {node.data.kind}
          </span>
          <h2 className="text-lg font-semibold text-slate-900">Property inspector</h2>
          <p className="text-sm text-slate-500">
            Live-edit the selected card and tune its configuration.
          </p>
        </div>

        <button
          type="button"
          onClick={() => setShowJsonEditor((current) => !current)}
          className="rounded-xl border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50"
        >
          {showJsonEditor ? "Basic view" : "JSON view"}
        </button>
      </div>

      <div className="space-y-4 overflow-y-auto pr-1">
        <div className="space-y-2">
          <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
            Label
          </label>
          <input
            type="text"
            value={node.data.label}
            onChange={(event) =>
              updateNodeData(node.id, { label: event.target.value })
            }
            className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-100"
          />
        </div>

        <div className="space-y-2">
          <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
            Subtitle
          </label>
          <input
            type="text"
            value={node.data.subtitle}
            onChange={(event) =>
              updateNodeData(node.id, { subtitle: event.target.value })
            }
            className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-100"
          />
        </div>

        <div className="space-y-2">
          <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
            Description
          </label>
          <textarea
            value={node.data.description}
            onChange={(event) =>
              updateNodeData(node.id, { description: event.target.value })
            }
            rows={3}
            className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-100"
          />
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
              Status
            </label>
            <select
              value={node.data.status}
              onChange={(event) =>
                updateNodeData(node.id, {
                  status: event.target.value as WorkflowNode["data"]["status"],
                })
              }
              className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-100"
            >
              <option value="draft">Draft</option>
              <option value="ready">Ready</option>
              <option value="live">Live</option>
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
              Accent
            </label>
            <input
              type="color"
              value={node.data.accent}
              onChange={(event) =>
                updateNodeData(node.id, { accent: event.target.value })
              }
              className="h-[50px] w-full rounded-2xl border border-slate-200 bg-white px-2 py-2"
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
            Notes
          </label>
          <textarea
            value={node.data.notes}
            onChange={(event) =>
              updateNodeData(node.id, { notes: event.target.value })
            }
            rows={4}
            className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-100"
          />
        </div>

        <div className="space-y-3 rounded-3xl border border-slate-200 bg-slate-50 p-4">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-sm font-semibold text-slate-900">Config map</h3>
              <p className="text-xs text-slate-500">
                Lightweight key-value settings for this node.
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                updateNodeData(node.id, {
                  config: {
                    ...node.data.config,
                    [`field_${configEntries.length + 1}`]: "new value",
                  },
                })
              }
              className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-100"
            >
              Add field
            </button>
          </div>

          <div className="space-y-3">
            {configEntries.map(([key, value]) => (
              <div key={key} className="space-y-2">
                <div className="flex items-center justify-between gap-3">
                  <label className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
                    {key}
                  </label>
                  <button
                    type="button"
                    onClick={() => {
                      const nextConfig = { ...node.data.config };
                      delete nextConfig[key];
                      updateNodeData(node.id, { config: nextConfig });
                    }}
                    className="text-xs font-semibold text-rose-600 transition hover:text-rose-700"
                  >
                    Remove
                  </button>
                </div>
                <input
                  type="text"
                  value={value}
                  onChange={(event) =>
                    updateNodeData(node.id, {
                      config: {
                        ...node.data.config,
                        [key]: event.target.value,
                      },
                    })
                  }
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-100"
                />
              </div>
            ))}
          </div>
        </div>

        {showJsonEditor ? (
          <div className="space-y-3 rounded-3xl border border-slate-200 bg-slate-950 p-4 text-white">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-sm font-semibold">Advanced JSON</h3>
                <p className="text-xs text-slate-300">
                  Paste JSON and apply it back to the selected node.
                </p>
              </div>
              <button
                type="button"
                onClick={() => setJsonDraft(JSON.stringify(node.data, null, 2))}
                className="rounded-xl border border-white/15 px-3 py-2 text-xs font-semibold text-white transition hover:border-white/30 hover:bg-white/10"
              >
                Reset
              </button>
            </div>

            <textarea
              value={jsonDraft}
              onChange={(event) => {
                setJsonDraft(event.target.value);
                setJsonError(null);
              }}
              rows={12}
              className="w-full rounded-2xl border border-white/10 bg-slate-900 px-4 py-3 font-mono text-xs text-slate-100 outline-none transition focus:border-sky-400 focus:ring-4 focus:ring-sky-500/10"
            />

            {jsonError ? (
              <p className="rounded-2xl border border-rose-500/30 bg-rose-500/10 px-4 py-3 text-xs text-rose-200">
                {jsonError}
              </p>
            ) : null}

            <button
              type="button"
              onClick={() => {
                try {
                  const parsed = JSON.parse(jsonDraft) as Partial<WorkflowNode["data"]>;
                  replaceNodeData(node.id, {
                    ...node.data,
                    ...parsed,
                    config: {
                      ...node.data.config,
                      ...parsed.config,
                    },
                  });
                  setJsonError(null);
                } catch (error) {
                  setJsonError(
                    error instanceof Error ? error.message : "Invalid JSON.",
                  );
                }
              }}
              className="rounded-2xl bg-white px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-slate-100"
            >
              Apply JSON
            </button>
          </div>
        ) : null}
      </div>
    </aside>
  );
}
